-- Modify "supply_connections" table
ALTER TABLE `supply_connections` ADD COLUMN `sync_task_id` bigint unsigned NOT NULL DEFAULT 0, ADD COLUMN `sync_lease_token` varchar(255) NOT NULL DEFAULT "", ADD COLUMN `sync_lease_until` bigint NOT NULL DEFAULT 0;
-- Modify "supply_sync_tasks" table
ALTER TABLE `supply_sync_tasks` ADD COLUMN `request_key` varchar(64) NULL, ADD COLUMN `request_hash` varchar(64) NULL, ADD COLUMN `import_payload` json NULL, ADD UNIQUE INDEX `supplysynctask_connection_id_request_key` (`connection_id`, `request_key`);
-- Create "supply_import_items" table
CREATE TABLE `supply_import_items` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `task_id` bigint unsigned NOT NULL, `code` varchar(128) NOT NULL, `name` varchar(1024) NOT NULL, `snapshot` json NOT NULL, `state` varchar(20) NOT NULL DEFAULT "pending", `stage` varchar(20) NOT NULL DEFAULT "import", `attempts` bigint NOT NULL DEFAULT 0, `next_attempt_at` bigint NOT NULL DEFAULT 0, `saved` bool NOT NULL DEFAULT 0, `created` bool NOT NULL DEFAULT 0, `activate_after_stock` bool NOT NULL DEFAULT 0, `local_product_id` bigint unsigned NOT NULL DEFAULT 0, `local_revision` varchar(255) NOT NULL DEFAULT "", `error_code` varchar(64) NOT NULL DEFAULT "", `error_summary` varchar(500) NOT NULL DEFAULT "", PRIMARY KEY (`id`), UNIQUE INDEX `supplyimportitem_task_id_code` (`task_id`, `code`), INDEX `supplyimportitem_task_id_state_next_attempt_at` (`task_id`, `state`, `next_attempt_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
